SELECT
	ISNULL(MAX(A.MST_NO), 10000) AS MST_NO
FROM dbo.TWK_MONTH_SCHEDULE A
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
  AND A.MST_DATE = #{MST_DATE} AND A.MST_MONTH = #{MST_MONTH}
